/**
 * The "No internet" scene that sits over Week 2's hero — cloud, dinosaur,
 * ground line, cacti, and the caption beneath them.
 *
 * Source art: public/gogleinternet.png. That file is 1890x3360 and 98%
 * transparent, so this is the artwork cropped to its own bounds and scaled to
 * the size it renders at (840x659 for a 420px placement at 2x).
 *
 * Held as a data URI rather than a URL because the hero is baked by Puppeteer:
 * the render box fetches nothing from localhost, so a relative path would come
 * out missing every time images were generated on a dev machine — CRITIQUE #8.
 * The on-screen preview uses the file in public/ instead, so the bundle only
 * pays for this string where it is actually needed.
 */
export const W2_HERO_OVERLAY_URI = 'data:image/png;base64,'
